export enum VoiceName {
  Puck = 'Puck',
  Charon = 'Charon',
  Kore = 'Kore',
  Fenrir = 'Fenrir',
  Aoede = 'Aoede',
}

export interface AudioChunk {
  id: number;
  text: string;
  status: 'pending' | 'generating' | 'completed' | 'error';
  data?: Uint8Array; // Raw PCM data (Int16)
}

export interface GenerationState {
  isGenerating: boolean;
  progress: number;
  totalChunks: number;
  currentChunkIndex: number;
  error?: string;
}

export const SAMPLE_RATE = 24000;
export const NUM_CHANNELS = 1;

import { SAMPLE_RATE, NUM_CHANNELS } from '../types';

/**
 * Splits text into sentences using regex similar to the Python script.
 * Looks for . ! ? followed by whitespace.
 */
export const splitIntoSentences = (text: string): string[] => {
  const cleanedText = text.replace(/\s+/g, ' ').trim();
  // Split using lookbehind for sentence terminators
  // JS regex lookbehind support is good in modern browsers
  // Fallback split logic if complex regex causes issues, but this is standard now.
  const sentences = cleanedText.split(/(?<=[.!?])\s+/);
  return sentences.filter(s => s.trim().length > 0);
};

/**
 * Groups sentences into chunks that do not exceed maxChars.
 */
export const createSmartChunks = (text: string, maxChars: number = 2000): string[] => {
  const sentences = splitIntoSentences(text);
  const chunks: string[] = [];
  let currentChunk = "";

  for (const sentence of sentences) {
    if (currentChunk.length + sentence.length + 1 <= maxChars) {
      currentChunk += (currentChunk ? " " : "") + sentence;
    } else {
      if (currentChunk) {
        chunks.push(currentChunk);
      }
      // If a single sentence is huge (unlikely but possible), it becomes its own chunk
      currentChunk = sentence;
    }
  }

  if (currentChunk) {
    chunks.push(currentChunk);
  }

  return chunks;
};

/**
 * Decodes a base64 string into a Uint8Array.
 */
export const base64ToUint8Array = (base64: string): Uint8Array => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

/**
 * Concatenates multiple Uint8Arrays (Raw PCM Int16 data) into one.
 */
export const concatenateAudioBuffers = (buffers: Uint8Array[]): Uint8Array => {
  const totalLength = buffers.reduce((acc, b) => acc + b.length, 0);
  const result = new Uint8Array(totalLength);
  let offset = 0;
  for (const buffer of buffers) {
    result.set(buffer, offset);
    offset += buffer.length;
  }
  return result;
};

/**
 * Writes a WAV header for the given PCM data.
 * Assumes 16-bit PCM, Monophonic, 24kHz (default Gemini output).
 */
export const createWavFile = (pcmData: Uint8Array): Blob => {
  const wavHeader = new ArrayBuffer(44);
  const view = new DataView(wavHeader);

  // RIFF chunk descriptor
  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + pcmData.length, true); // ChunkSize
  writeString(view, 8, 'WAVE');

  // fmt sub-chunk
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true); // Subchunk1Size (16 for PCM)
  view.setUint16(20, 1, true); // AudioFormat (1 for PCM)
  view.setUint16(22, NUM_CHANNELS, true); // NumChannels
  view.setUint32(24, SAMPLE_RATE, true); // SampleRate
  view.setUint32(28, SAMPLE_RATE * NUM_CHANNELS * 2, true); // ByteRate
  view.setUint16(32, NUM_CHANNELS * 2, true); // BlockAlign
  view.setUint16(34, 16, true); // BitsPerSample

  // data sub-chunk
  writeString(view, 36, 'data');
  view.setUint32(40, pcmData.length, true); // Subchunk2Size

  const blob = new Blob([wavHeader, pcmData], { type: 'audio/wav' });
  return blob;
};

const writeString = (view: DataView, offset: number, string: string) => {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
};

/**
 * Helper to play raw PCM buffer in browser for preview
 */
export const playAudioBuffer = async (pcmData: Uint8Array, context: AudioContext): Promise<void> => {
  // Convert Int16 bytes to Float32 for Web Audio API
  const int16 = new Int16Array(pcmData.buffer);
  const float32 = new Float32Array(int16.length);
  for (let i = 0; i < int16.length; i++) {
    float32[i] = int16[i] / 32768.0;
  }

  const audioBuffer = context.createBuffer(NUM_CHANNELS, float32.length, SAMPLE_RATE);
  audioBuffer.copyToChannel(float32, 0);

  const source = context.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(context.destination);
  source.start();
};

import { GoogleGenAI, Modality } from "@google/genai";
import { VoiceName } from "../types";

// Initialize the client
// NOTE: In a real environment, process.env.API_KEY is replaced by the bundler or runtime environment.
// The system prompt guarantees this is available.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = 'gemini-2.5-flash-preview-tts';

export const generateSpeechChunk = async (
  text: string,
  voice: VoiceName
): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          { text: text }
        ]
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: {
              voiceName: voice,
            },
          },
        },
      },
    });

    // Extract inline data
    const candidate = response.candidates?.[0];
    const part = candidate?.content?.parts?.[0];

    if (!part || !part.inlineData || !part.inlineData.data) {
      throw new Error("No audio data returned from Gemini API");
    }

    return part.inlineData.data;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React from 'react';
import { VoiceName } from '../types';
import { Mic } from 'lucide-react';

interface VoiceSelectorProps {
  selectedVoice: VoiceName;
  onVoiceChange: (voice: VoiceName) => void;
  disabled?: boolean;
}

const VoiceSelector: React.FC<VoiceSelectorProps> = ({ selectedVoice, onVoiceChange, disabled }) => {
  return (
    <div className="flex flex-col gap-2">
      <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
        <Mic className="w-4 h-4" />
        Select Voice
      </label>
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-2">
        {Object.values(VoiceName).map((voice) => (
          <button
            key={voice}
            onClick={() => onVoiceChange(voice)}
            disabled={disabled}
            className={`
              px-4 py-3 rounded-lg border text-sm font-medium transition-all
              ${selectedVoice === voice 
                ? 'bg-blue-600 text-white border-blue-600 shadow-md ring-2 ring-blue-200' 
                : 'bg-white text-slate-700 border-slate-200 hover:border-blue-400 hover:bg-slate-50'
              }
              ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
            `}
          >
            {voice}
          </button>
        ))}
      </div>
    </div>
  );
};

export default VoiceSelector;

import React, { useRef } from 'react';
import { FileText, Upload } from 'lucide-react';

interface TextInputProps {
  text: string;
  onTextChange: (text: string) => void;
  disabled?: boolean;
}

const TextInput: React.FC<TextInputProps> = ({ text, onTextChange, disabled }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const content = event.target?.result as string;
        onTextChange(content);
      };
      reader.readAsText(file);
    }
  };

  return (
    <div className="flex flex-col gap-2 h-full">
      <div className="flex justify-between items-center mb-1">
        <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
          <FileText className="w-4 h-4" />
          Script
        </label>
        <div className="flex gap-2">
           <button
            onClick={() => fileInputRef.current?.click()}
            disabled={disabled}
            className="text-xs flex items-center gap-1 text-blue-600 hover:text-blue-800 disabled:opacity-50 font-medium px-2 py-1 rounded hover:bg-blue-50 transition-colors"
          >
            <Upload className="w-3 h-3" />
            Import .txt
          </button>
          <input
            type="file"
            accept=".txt"
            ref={fileInputRef}
            className="hidden"
            onChange={handleFileUpload}
          />
        </div>
      </div>
      <textarea
        value={text}
        onChange={(e) => onTextChange(e.target.value)}
        disabled={disabled}
        placeholder="Enter your text here or upload a .txt file..."
        className="w-full min-h-[200px] p-4 rounded-xl border border-slate-200 focus:border-blue-500 focus:ring-2 focus:ring-blue-100 outline-none resize-y text-slate-800 leading-relaxed shadow-sm font-light text-lg transition-all"
      />
      <div className="text-right text-xs text-slate-400">
        {text.length} characters
      </div>
    </div>
  );
};

export default TextInput;

import React, { useState, useRef, useCallback } from 'react';
import { BookOpen, Play, Download, Loader2, Sparkles, StopCircle } from 'lucide-react';
import { VoiceName, AudioChunk, GenerationState } from './types';
import { createSmartChunks, base64ToUint8Array, concatenateAudioBuffers, createWavFile } from './utils/audioUtils';
import { generateSpeechChunk } from './services/geminiService';
import VoiceSelector from './components/VoiceSelector';
import TextInput from './components/TextInput';

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [voice, setVoice] = useState<VoiceName>(VoiceName.Fenrir);
  const [audioChunks, setAudioChunks] = useState<AudioChunk[]>([]);
  const [generationState, setGenerationState] = useState<GenerationState>({
    isGenerating: false,
    progress: 0,
    totalChunks: 0,
    currentChunkIndex: 0
  });
  const [finalBlob, setFinalBlob] = useState<Blob | null>(null);

  // Use a ref to track cancellation
  const abortRef = useRef<boolean>(false);

  const handleGenerate = useCallback(async () => {
    if (!text.trim()) return;

    // Reset State
    setFinalBlob(null);
    setAudioChunks([]);
    setGenerationState({
      isGenerating: true,
      progress: 0,
      totalChunks: 0,
      currentChunkIndex: 0,
      error: undefined
    });
    abortRef.current = false;

    // Split text
    const textChunks = createSmartChunks(text, 2000); // 2000 chars per chunk safe limit
    const initialAudioChunks: AudioChunk[] = textChunks.map((t, i) => ({
      id: i,
      text: t,
      status: 'pending'
    }));

    setAudioChunks(initialAudioChunks);
    setGenerationState(prev => ({ ...prev, totalChunks: initialAudioChunks.length }));

    const collectedBuffers: Uint8Array[] = [];

    try {
      for (let i = 0; i < textChunks.length; i++) {
        if (abortRef.current) break;

        setGenerationState(prev => ({ ...prev, currentChunkIndex: i + 1, progress: (i / textChunks.length) * 100 }));

        // Update chunk status to generating
        setAudioChunks(prev => prev.map(c => c.id === i ? { ...c, status: 'generating' } : c));

        // Generate audio
        // Retry logic inside the loop
        let pcmData: Uint8Array | null = null;
        let attempts = 0;

        while(attempts < 3 && !pcmData && !abortRef.current) {
             try {
                 const base64Data = await generateSpeechChunk(textChunks[i], voice);
                 pcmData = base64ToUint8Array(base64Data);
             } catch (err) {
                 console.warn(`Attempt ${attempts + 1} failed for chunk ${i}`, err);
                 attempts++;
                 await new Promise(r => setTimeout(r, 1000 * attempts)); // Exponential backoffish
             }
        }

        if (abortRef.current) break;

        if (pcmData) {
            collectedBuffers.push(pcmData);
            setAudioChunks(prev => prev.map(c => c.id === i ? { ...c, status: 'completed', data: pcmData } : c));
        } else {
            throw new Error(`Failed to generate audio for chunk ${i+1}`);
        }

        // Small delay to be nice to API
        await new Promise(resolve => setTimeout(resolve, 500));
      }

      if (!abortRef.current && collectedBuffers.length > 0) {
          const combinedBuffer = concatenateAudioBuffers(collectedBuffers);
          const wavBlob = createWavFile(combinedBuffer);
          setFinalBlob(wavBlob);
          setGenerationState(prev => ({ ...prev, isGenerating: false, progress: 100 }));
      } else {
          // If aborted, just stop
          setGenerationState(prev => ({ ...prev, isGenerating: false }));
      }

    } catch (error) {
      console.error(error);
      setGenerationState(prev => ({ 
          ...prev, 
          isGenerating: false, 
          error: error instanceof Error ? error.message : "An unexpected error occurred" 
      }));
    }
  }, [text, voice]);

  const handleStop = () => {
      abortRef.current = true;
      setGenerationState(prev => ({ ...prev, isGenerating: false }));
  };

  const downloadAudio = () => {
      if (!finalBlob) return;
      const url = URL.createObjectURL(finalBlob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `audiobook-${new Date().getTime()}.wav`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
            <div className="flex items-center gap-2">
                <div className="bg-blue-600 p-2 rounded-lg text-white">
                     <BookOpen size={20} />
                </div>
                <h1 className="text-xl font-bold text-slate-800 tracking-tight">Gemini Audiobook</h1>
            </div>
            <div className="text-sm font-medium text-slate-500 bg-slate-100 px-3 py-1 rounded-full">
                Powered by Gemini 2.5 Flash
            </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Intro Section */}
        <section className="text-center space-y-2 max-w-2xl mx-auto mb-8">
            <h2 className="text-3xl font-bold text-slate-900">Turn Text into Lifelike Speech</h2>
            <p className="text-slate-500">
                Generate high-quality audiobooks from text using Google's latest AI models. 
                Select a voice, paste your script, and let Gemini narrate for you.
            </p>
        </section>

        {/* Controls */}
        <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 md:p-8 space-y-6">
            <VoiceSelector 
                selectedVoice={voice} 
                onVoiceChange={setVoice} 
                disabled={generationState.isGenerating}
            />

            <TextInput 
                text={text} 
                onTextChange={setText} 
                disabled={generationState.isGenerating}
            />

            {/* Error Message */}
            {generationState.error && (
                <div className="bg-red-50 text-red-700 p-4 rounded-lg border border-red-200 text-sm">
                    <strong>Error:</strong> {generationState.error}
                </div>
            )}

            {/* Action Bar */}
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 pt-4 border-t border-slate-100">
                <div className="flex-1 w-full">
                    {generationState.isGenerating && (
                        <div className="space-y-2">
                            <div className="flex justify-between text-xs font-semibold text-slate-500 uppercase tracking-wide">
                                <span>Generating Chunk {generationState.currentChunkIndex} of {generationState.totalChunks}</span>
                                <span>{Math.round(generationState.progress)}%</span>
                            </div>
                            <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
                                <div 
                                    className="h-full bg-blue-600 transition-all duration-300 ease-out"
                                    style={{ width: `${generationState.progress}%` }}
                                />
                            </div>
                        </div>
                    )}
                    {!generationState.isGenerating && finalBlob && (
                         <div className="flex items-center gap-2 text-green-600 bg-green-50 px-3 py-2 rounded-lg text-sm font-medium border border-green-100">
                             <Sparkles className="w-4 h-4" />
                             Audiobook Ready! ({((finalBlob.size / 1024) / 1024).toFixed(2)} MB)
                         </div>
                    )}
                </div>

                <div className="flex gap-3 w-full sm:w-auto">
                     {generationState.isGenerating ? (
                         <button
                            onClick={handleStop}
                            className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 bg-red-100 text-red-700 font-semibold rounded-xl hover:bg-red-200 transition-colors"
                        >
                            <StopCircle size={20} />
                            Stop
                        </button>
                     ) : (
                        <button
                            onClick={handleGenerate}
                            disabled={!text || generationState.isGenerating}
                            className={`
                                flex-1 sm:flex-none flex items-center justify-center gap-2 px-8 py-3 rounded-xl font-semibold text-white shadow-lg shadow-blue-200 transition-all
                                ${!text 
                                    ? 'bg-slate-300 cursor-not-allowed shadow-none' 
                                    : 'bg-blue-600 hover:bg-blue-700 hover:scale-[1.02]'
                                }
                            `}
                        >
                            {generationState.isGenerating ? <Loader2 className="animate-spin" /> : <Sparkles size={20} />}
                            Generate Audiobook
                        </button>
                     )}
                </div>
            </div>
        </section>

        {/* Results Section */}
        {finalBlob && (
            <section className="bg-white rounded-2xl shadow-lg border border-slate-200 p-1">
                 <div className="p-6 md:p-8 flex flex-col md:flex-row items-center gap-6 justify-between bg-slate-50/50 rounded-xl">
                    <div className="flex items-center gap-4 w-full">
                        <div className="w-12 h-12 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center shrink-0">
                            <Play className="fill-current w-5 h-5 ml-1" />
                        </div>
                        <div className="w-full">
                            <audio 
                                controls 
                                className="w-full h-10 block" 
                                src={URL.createObjectURL(finalBlob)} 
                            />
                        </div>
                    </div>
                    <button
                        onClick={downloadAudio}
                        className="w-full md:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-slate-900 text-white font-medium rounded-xl hover:bg-slate-800 transition-colors"
                    >
                        <Download size={18} />
                        Download .WAV
                    </button>
                 </div>
            </section>
        )}

        {/* Debug/Chunk View (Optional but nice) */}
        {audioChunks.length > 0 && (
             <section className="space-y-4">
                 <h3 className="text-lg font-semibold text-slate-800 px-1">Processing Details</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                     {audioChunks.map((chunk) => (
                         <div 
                            key={chunk.id} 
                            className={`
                                p-4 rounded-xl border text-sm transition-colors
                                ${chunk.status === 'completed' ? 'bg-white border-green-200 shadow-sm' : ''}
                                ${chunk.status === 'generating' ? 'bg-blue-50 border-blue-200 ring-1 ring-blue-100' : ''}
                                ${chunk.status === 'pending' ? 'bg-slate-50 border-slate-100 text-slate-400' : ''}
                                ${chunk.status === 'error' ? 'bg-red-50 border-red-200' : ''}
                            `}
                        >
                             <div className="flex justify-between items-center mb-2">
                                 <span className="font-medium text-slate-500">Chunk {chunk.id + 1}</span>
                                 <span className={`
                                     text-xs font-bold px-2 py-0.5 rounded-full uppercase tracking-wider
                                     ${chunk.status === 'completed' ? 'text-green-700 bg-green-100' : ''}
                                     ${chunk.status === 'generating' ? 'text-blue-700 bg-blue-100' : ''}
                                     ${chunk.status === 'pending' ? 'text-slate-500 bg-slate-200' : ''}
                                 `}>
                                     {chunk.status}
                                 </span>
                             </div>
                             <p className="line-clamp-3 text-slate-600">{chunk.text}</p>
                         </div>
                     ))}
                 </div>
             </section>
        )}
      </main>
    </div>
  );
};

export default App;

