import { SAMPLE_RATE, NUM_CHANNELS } from '../types';

/**
 * Splits text into sentences using regex similar to the Python script.
 * Looks for . ! ? followed by whitespace.
 */
export const splitIntoSentences = (text: string): string[] => {
  const cleanedText = text.replace(/\s+/g, ' ').trim();
  // Split using lookbehind for sentence terminators
  // JS regex lookbehind support is good in modern browsers
  // Fallback split logic if complex regex causes issues, but this is standard now.
  const sentences = cleanedText.split(/(?<=[.!?])\s+/);
  return sentences.filter(s => s.trim().length > 0);
};

/**
 * Groups sentences into chunks that do not exceed maxChars.
 */
export const createSmartChunks = (text: string, maxChars: number = 2000): string[] => {
  const sentences = splitIntoSentences(text);
  const chunks: string[] = [];
  let currentChunk = "";

  for (const sentence of sentences) {
    if (currentChunk.length + sentence.length + 1 <= maxChars) {
      currentChunk += (currentChunk ? " " : "") + sentence;
    } else {
      if (currentChunk) {
        chunks.push(currentChunk);
      }
      // If a single sentence is huge (unlikely but possible), it becomes its own chunk
      currentChunk = sentence;
    }
  }

  if (currentChunk) {
    chunks.push(currentChunk);
  }

  return chunks;
};

/**
 * Decodes a base64 string into a Uint8Array.
 */
export const base64ToUint8Array = (base64: string): Uint8Array => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

/**
 * Concatenates multiple Uint8Arrays (Raw PCM Int16 data) into one.
 */
export const concatenateAudioBuffers = (buffers: Uint8Array[]): Uint8Array => {
  const totalLength = buffers.reduce((acc, b) => acc + b.length, 0);
  const result = new Uint8Array(totalLength);
  let offset = 0;
  for (const buffer of buffers) {
    result.set(buffer, offset);
    offset += buffer.length;
  }
  return result;
};

/**
 * Writes a WAV header for the given PCM data.
 * Assumes 16-bit PCM, Monophonic, 24kHz (default Gemini output).
 */
export const createWavFile = (pcmData: Uint8Array): Blob => {
  const wavHeader = new ArrayBuffer(44);
  const view = new DataView(wavHeader);

  // RIFF chunk descriptor
  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + pcmData.length, true); // ChunkSize
  writeString(view, 8, 'WAVE');

  // fmt sub-chunk
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true); // Subchunk1Size (16 for PCM)
  view.setUint16(20, 1, true); // AudioFormat (1 for PCM)
  view.setUint16(22, NUM_CHANNELS, true); // NumChannels
  view.setUint32(24, SAMPLE_RATE, true); // SampleRate
  view.setUint32(28, SAMPLE_RATE * NUM_CHANNELS * 2, true); // ByteRate
  view.setUint16(32, NUM_CHANNELS * 2, true); // BlockAlign
  view.setUint16(34, 16, true); // BitsPerSample

  // data sub-chunk
  writeString(view, 36, 'data');
  view.setUint32(40, pcmData.length, true); // Subchunk2Size

  const blob = new Blob([wavHeader, pcmData], { type: 'audio/wav' });
  return blob;
};

// Define global type for lamejs since we load it via script tag
declare global {
  interface Window {
    lamejs: any;
  }
}

/**
 * Encodes PCM data to MP3 using lamejs
 */
export const createMp3File = (pcmData: Uint8Array): Blob => {
  if (!window.lamejs) {
    throw new Error("MP3 encoder library (lamejs) failed to load.");
  }

  // Ensure we are working with 16-bit samples
  const samples = new Int16Array(pcmData.buffer, pcmData.byteOffset, pcmData.byteLength / 2);

  // Initialize encoder: 1 channel, 24000 Hz, 128kbps
  const mp3encoder = new window.lamejs.Mp3Encoder(NUM_CHANNELS, SAMPLE_RATE, 128);
  const mp3Data: Uint8Array[] = [];

  // Use a block size that is a multiple of 576 or 1152 for efficiency, 
  // but lamejs handles chunking. We chunk to avoid blocking UI too much if we were async,
  // but here we just process.
  const blockSize = 1152; 

  for (let i = 0; i < samples.length; i += blockSize) {
    const sampleChunk = samples.subarray(i, i + blockSize);
    const mp3buf = mp3encoder.encodeBuffer(sampleChunk);
    if (mp3buf.length > 0) {
      mp3Data.push(mp3buf);
    }
  }

  const mp3buf = mp3encoder.flush();
  if (mp3buf.length > 0) {
    mp3Data.push(mp3buf);
  }

  return new Blob(mp3Data, { type: 'audio/mp3' });
};

const writeString = (view: DataView, offset: number, string: string) => {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
};

/**
 * Helper to play raw PCM buffer in browser for preview
 */
export const playAudioBuffer = async (pcmData: Uint8Array, context: AudioContext): Promise<void> => {
  // Convert Int16 bytes to Float32 for Web Audio API
  const int16 = new Int16Array(pcmData.buffer, pcmData.byteOffset, pcmData.byteLength / 2);
  const float32 = new Float32Array(int16.length);
  for (let i = 0; i < int16.length; i++) {
    float32[i] = int16[i] / 32768.0;
  }

  const audioBuffer = context.createBuffer(NUM_CHANNELS, float32.length, SAMPLE_RATE);
  audioBuffer.copyToChannel(float32, 0);

  const source = context.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(context.destination);
  source.start();
};

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { BookOpen, Play, Download, Loader2, Sparkles, StopCircle } from 'lucide-react';
import { VoiceName, ModelId, AudioChunk, GenerationState, AudioFormat } from './types';
import { createSmartChunks, base64ToUint8Array, concatenateAudioBuffers, createWavFile, createMp3File } from './utils/audioUtils';
import { generateSpeechChunk } from './services/geminiService';
import VoiceSelector from './components/VoiceSelector';
import ModelSelector from './components/ModelSelector';
import FormatSelector from './components/FormatSelector';
import TextInput from './components/TextInput';

const App: React.FC = () => {
  const [text, setText] = useState<string>('');
  const [voice, setVoice] = useState<VoiceName>(VoiceName.Fenrir);
  const [model, setModel] = useState<ModelId>(ModelId.Flash);
  const [format, setFormat] = useState<AudioFormat>('wav');

  const [audioChunks, setAudioChunks] = useState<AudioChunk[]>([]);
  const [generationState, setGenerationState] = useState<GenerationState>({
    isGenerating: false,
    progress: 0,
    totalChunks: 0,
    currentChunkIndex: 0
  });
  const [finalBlob, setFinalBlob] = useState<Blob | null>(null);

  // Use a ref to track cancellation
  const abortRef = useRef<boolean>(false);

  // Helper to generate blob from existing chunks
  const generateBlobFromChunks = useCallback((chunks: AudioChunk[], targetFormat: AudioFormat) => {
      const completedChunks = chunks.filter(c => c.status === 'completed' && c.data);
      if (completedChunks.length === 0 || completedChunks.length !== chunks.length) return null;

      const buffers = completedChunks.map(c => c.data!);
      const combinedBuffer = concatenateAudioBuffers(buffers);

      if (targetFormat === 'wav') {
          return createWavFile(combinedBuffer);
      } else {
          return createMp3File(combinedBuffer);
      }
  }, []);

  // Effect to update blob when format changes (if chunks are ready)
  useEffect(() => {
    if (!generationState.isGenerating && audioChunks.length > 0 && audioChunks.every(c => c.status === 'completed')) {
        const blob = generateBlobFromChunks(audioChunks, format);
        setFinalBlob(blob);
    }
  }, [format, audioChunks, generationState.isGenerating, generateBlobFromChunks]);


  const handleGenerate = useCallback(async () => {
    if (!text.trim()) return;

    // Reset State
    setFinalBlob(null);
    setAudioChunks([]);
    setGenerationState({
      isGenerating: true,
      progress: 0,
      totalChunks: 0,
      currentChunkIndex: 0,
      error: undefined
    });
    abortRef.current = false;

    // Split text
    const textChunks = createSmartChunks(text, 2000); // 2000 chars per chunk safe limit
    const initialAudioChunks: AudioChunk[] = textChunks.map((t, i) => ({
      id: i,
      text: t,
      status: 'pending'
    }));

    setAudioChunks(initialAudioChunks);
    setGenerationState(prev => ({ ...prev, totalChunks: initialAudioChunks.length }));

    const collectedBuffers: Uint8Array[] = [];

    try {
      for (let i = 0; i < textChunks.length; i++) {
        if (abortRef.current) break;

        setGenerationState(prev => ({ ...prev, currentChunkIndex: i + 1, progress: (i / textChunks.length) * 100 }));

        // Update chunk status to generating
        setAudioChunks(prev => prev.map(c => c.id === i ? { ...c, status: 'generating' } : c));

        // Generate audio
        let pcmData: Uint8Array | null = null;
        let attempts = 0;
        const maxRetries = 6; // Increased retries for rate limits

        while(attempts < maxRetries && !pcmData && !abortRef.current) {
             try {
                 const base64Data = await generateSpeechChunk(textChunks[i], voice, model);
                 pcmData = base64ToUint8Array(base64Data);
             } catch (err: any) {
                 const errorMessage = err?.message || err?.toString() || "";
                 const isRateLimit = errorMessage.includes('429') || errorMessage.includes('quota') || errorMessage.includes('RESOURCE_EXHAUSTED');

                 console.warn(`Attempt ${attempts + 1} failed for chunk ${i + 1}. Rate Limit: ${isRateLimit}`, err);

                 attempts++;

                 if (attempts >= maxRetries) {
                     console.error(`Max retries reached for chunk ${i + 1}`);
                     // If we fail after max retries, throw the error to stop the process
                     throw new Error(`Failed to generate part ${i + 1} after ${maxRetries} attempts. ${isRateLimit ? "Quota exceeded." : errorMessage}`);
                 }

                 // Calculate delay
                 // If rate limit, wait significantly longer (10s + linear backoff)
                 // If other error, use exponential backoff
                 let delay = 2000 * Math.pow(2, attempts); // 4s, 8s, 16s...

                 if (isRateLimit) {
                     delay = 10000 + (attempts * 5000); // 15s, 20s, 25s, 30s...
                     setGenerationState(prev => ({ 
                         ...prev, 
                         error: `Rate limit reached. Pausing for ${delay/1000} seconds before retrying chunk ${i + 1}...` 
                     }));
                 }

                 await new Promise(r => setTimeout(r, delay));

                 // Clear transient error message after waiting
                 if (isRateLimit) {
                     setGenerationState(prev => ({ ...prev, error: undefined }));
                 }
             }
        }

        if (abortRef.current) break;

        if (pcmData) {
            collectedBuffers.push(pcmData);
            // We store the RAW PCM data in the chunk
            setAudioChunks(prev => prev.map(c => c.id === i ? { ...c, status: 'completed', data: pcmData! } : c));
        }

        // Delay between chunks to avoid hitting RPM limits immediately again
        // 2 seconds is safer than 500ms
        if (i < textChunks.length - 1) {
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }

      if (!abortRef.current && collectedBuffers.length > 0) {
          // Final generation
          const combinedBuffer = concatenateAudioBuffers(collectedBuffers);
          let blob: Blob;
          if (format === 'wav') {
              blob = createWavFile(combinedBuffer);
          } else {
              blob = createMp3File(combinedBuffer);
          }
          setFinalBlob(blob);
          setGenerationState(prev => ({ ...prev, isGenerating: false, progress: 100 }));
      } else {
          // If aborted, just stop
          setGenerationState(prev => ({ ...prev, isGenerating: false }));
      }

    } catch (error) {
      console.error(error);
      setGenerationState(prev => ({ 
          ...prev, 
          isGenerating: false, 
          error: error instanceof Error ? error.message : "An unexpected error occurred" 
      }));
    }
  }, [text, voice, model, format]);

  const handleStop = () => {
      abortRef.current = true;
      setGenerationState(prev => ({ ...prev, isGenerating: false }));
  };

  const downloadAudio = () => {
      if (!finalBlob) return;
      const url = URL.createObjectURL(finalBlob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `audiobook-${new Date().getTime()}.${format}`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
            <div className="flex items-center gap-2">
                <div className="bg-blue-600 p-2 rounded-lg text-white">
                     <BookOpen size={20} />
                </div>
                <h1 className="text-xl font-bold text-slate-800 tracking-tight">Gemini Audiobook</h1>
            </div>
            <div className="text-sm font-medium text-slate-500 bg-slate-100 px-3 py-1 rounded-full">
                Powered by Gemini 2.5
            </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Intro Section */}
        <section className="text-center space-y-2 max-w-2xl mx-auto mb-8">
            <h2 className="text-3xl font-bold text-slate-900">Turn Text into Lifelike Speech</h2>
            <p className="text-slate-500">
                Generate high-quality audiobooks from text using Google's latest AI models. 
                Select a model and voice, paste your script, and let Gemini narrate for you.
            </p>
        </section>

        {/* Controls */}
        <section className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 md:p-8 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <ModelSelector 
                    selectedModel={model}
                    onModelChange={setModel}
                    disabled={generationState.isGenerating}
                />
                <FormatSelector 
                    selectedFormat={format}
                    onFormatChange={setFormat}
                    disabled={generationState.isGenerating}
                />
            </div>

            <VoiceSelector 
                selectedVoice={voice} 
                onVoiceChange={setVoice} 
                disabled={generationState.isGenerating}
            />

            <TextInput 
                text={text} 
                onTextChange={setText} 
                disabled={generationState.isGenerating}
            />

            {/* Error Message */}
            {generationState.error && (
