                     )}
                </div>
            </div>
        )}

      </main>

      {/* Settings Modal (Overlay) */}
      {showSettings && (
          <div className="fixed inset-0 bg-zinc-950/70 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
              <div className="bg-white rounded-xl shadow-2xl max-w-md w-full overflow-hidden scale-100 border border-zinc-200">
                  <div className="px-6 py-4 border-b border-zinc-100 flex justify-between items-center bg-zinc-50">
                      <h3 className="font-bold text-zinc-800 flex items-center gap-2">
