                      </button>
                  </div>

                  <div className="p-6 space-y-6">
                      {/* Paid Key Promo */}
                      <div className="bg-zinc-900 rounded-xl p-5 text-center space-y-3 relative overflow-hidden ring-1 ring-zinc-800">
                           <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-600/20 blur-3xl -mr-10 -mt-10" />
                           <div className="absolute bottom-0 left-0 w-32 h-32 bg-amber-600/10 blur-3xl -ml-10 -mb-10" />

                           <div className="w-10 h-10 bg-indigo-500/20 text-indigo-400 rounded-full flex items-center justify-center mx-auto mb-2 relative z-10">
                                <ShieldCheck size={20} />
                           </div>
                           <h4 className="text-white font-bold relative z-10">Rate Limits? Go Pro.</h4>
                           <p className="text-xs text-zinc-400 leading-relaxed relative z-10">
                               Gemini 2.5 Pro models require a paid cloud project for high-volume generation.
                           </p>
                           <button 
                               onClick={handleSelectPaidKey}
                               className="w-full py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-lg text-sm transition-colors relative z-10 shadow-lg shadow-indigo-900/50"
                           >
                               Select Paid API Key
                           </button>
                           <a href="https://ai.google.dev/pricing" target="_blank" rel="noreferrer" className="text-[10px] text-zinc-500 hover:text-zinc-300 underline block mt-2 relative z-10">
                               View Pricing Documentation
                           </a>
                      </div>

                      <div className="space-y-2">
                          <label className="text-sm font-semibold text-zinc-700">Manual API Key (Optional)</label>
                          <div className="flex gap-2">
                              <input 
                                  type="password" 
                                  value={userApiKey}
                                  onChange={handleApiKeyChange}
                                  placeholder="Paste key here..."
                                  className={`flex-1 px-3 py-2 rounded-lg border text-sm outline-none transition-all ${keyStatus === 'valid' ? 'border-emerald-300 bg-emerald-50' : 'border-zinc-300 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100'}`}
                              />
                              <button onClick={testApiKey} disabled={!userApiKey} className="px-3 py-2 bg-zinc-100 border border-zinc-200 rounded-lg text-sm font-medium hover:bg-zinc-200 transition-colors">
                                  {keyStatus === 'validating' ? <Loader2 size={14} className="animate-spin"/> : 'Test'}
