                        onEnded={handleAudioEnded}
                        className="w-full h-8" 
                    />
                    <div className="text-[10px] text-zinc-500 font-medium">
                        {previewUrl ? `Previewing Chunk ${previewChunkCount} / ${readyChunksCount} ready` : 'Full Audiobook Playback'}
                    </div>
