const handleGeminiError = (error: any) => {
  let message = "An unexpected error occurred.";
  let isRateLimit = false;
  let isQuotaZero = false;

  // Helper to check for rate limit keywords
  const checkRateLimit = (msg: string) => {
      const lowerMsg = msg.toLowerCase();
      // Check for hard limit 0 (Free tier exhaustion or Model not available in tier)
      if (lowerMsg.includes('limit: 0') || lowerMsg.includes('limit:0')) {
          isQuotaZero = true;
          return true;
      }

      return lowerMsg.includes('429') || 
             lowerMsg.includes('quota') || 
             lowerMsg.includes('resource_exhausted') || 
             lowerMsg.includes('too many requests');
  };

  if (error instanceof Error) {
    message = error.message;
    // Attempt to parse JSON in message (SDK sometimes throws JSON string)
    try {
      if (message.trim().startsWith('{')) {
        const parsed = JSON.parse(message);
        if (parsed.error) {
          message = parsed.error.message || message;
          if (parsed.error.code === 429 || parsed.error.status === 'RESOURCE_EXHAUSTED') {
             isRateLimit = true;
             if (message.includes('limit: 0')) isQuotaZero = true;
          }
        }
      }
    } catch (e) {}
  } else if (typeof error === 'object' && error !== null) {
      // Handle raw object errors if thrown directly
      if ((error as any).error) {
         const errObj = (error as any).error;
         message = errObj.message || JSON.stringify(errObj);
         if (errObj.code === 429 || errObj.status === 'RESOURCE_EXHAUSTED') {
            isRateLimit = true;
            if (message.includes('limit: 0')) isQuotaZero = true;
         }
      } else {
         message = JSON.stringify(error);
      }
  } else {
      message = String(error);
  }

  // Fallback check on the final message string
  if (!isRateLimit && checkRateLimit(message)) {
      isRateLimit = true;
  }

  if (isQuotaZero) {
      console.error("Gemini API Quota Zero:", message);
      // Hard stop error
      throw new Error("Quota Limit is 0. This model requires a Paid API Key (Billing Account) or is not available in your tier/region.");
  }

  // Log appropriate level
  if (isRateLimit) {
      console.warn("Gemini API Rate Limit Hit:", message);
  } else {
      console.error("Gemini API Error:", error);
  }

  const enhancedError = new Error(message);
  (enhancedError as any).isRateLimit = isRateLimit;
  throw enhancedError;
};

