        console.warn("Style generation failed, using default", error);
        return "Digital art, high resolution, cinematic lighting, vivid colors.";
    }
};

/**
 * Generates sequential scene prompts based on the chunk text and global style.
 */
export const generateScenePrompts = async (chunkText: string, style: string, count: number): Promise<string[]> => {
    try {
        const ai = getClient();
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: `
                You are a storyboard artist and prompter.

                Visual Vision / Style:
                "${style}"

                Current Story Segment:
                "${chunkText}"

                Task:
                Create exactly ${count} distinct, sequential image generation prompts to visualize this story segment.

                Requirements for each prompt:
                1.  **Full Sentences Only**: Do not use fragments. Describe the scene completely.
                2.  **Meaningful Visuals**: Focus on the specific moment, action, or emotion described in the sequence.
                3.  **Visual Objects & Backgrounds**: Explicitly mention the setting, props, and environment.
                4.  **Characters**: Describe characters' appearance and expressions if present.
                5.  **Typography**: If relevant to the style (e.g., a sign, a letter, a title card), describe it visually.
                6.  **Style Integration**: Ensure the global style (colors, medium) is woven into the description.
                7.  **Think in Scenes**: If count > 1, progress the visuals sequentially through the chunk's narrative.

                Output:
                A JSON array of strings. Each string is a standalone prompt.
            `,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING }
                }
            }
        });

        const jsonStr = response.text?.trim();
        if (!jsonStr) return [`${style}. Scene: ${chunkText}`];

        return JSON.parse(jsonStr);
    } catch (error) {
        console.warn("Scene prompt generation failed, falling back to raw text.", error);
        // Fallback: just repeat the chunk text with style if LLM fails
        return Array(count).fill(`${style}. Scene description: ${chunkText}`);
    }
};

/**
 * Generates an image using Nano Banana (gemini-2.5-flash-image)
 */
export const generateNanobanaImage = async (prompt: string): Promise<string> => {
    try {
        const ai = getClient();
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: prompt }]
            },
            config: {
                imageConfig: {
                    aspectRatio: "1:1"
                }
            }
        });

        // Iterate parts to find image
        const parts = response.candidates?.[0]?.content?.parts;
        if (parts) {
            for (const part of parts) {
                if (part.inlineData && part.inlineData.data) {
                    return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
                }
            }
        }

        throw new Error("No image data found in response");
    } catch (error) {
        handleGeminiError(error);
        throw error;
    }
};

import React, { useState, useRef } from 'react';
import { VoiceName, ModelId } from '../types';
import { Play, Square, Loader2, AlertCircle } from 'lucide-react';
import { generateSpeechChunk } from '../services/geminiService';
import { base64ToUint8Array, createWavFile } from '../utils/audioUtils';

interface VoiceSelectorProps {
  selectedVoice: VoiceName;
  onVoiceChange: (voice: VoiceName) => void;
  disabled?: boolean;
  model: ModelId;
  previewText: string;
  styleInstruction: string;
}

const VoiceSelector: React.FC<VoiceSelectorProps> = ({ selectedVoice, onVoiceChange, disabled, model, previewText, styleInstruction }) => {

  const [playingVoice, setPlayingVoice] = useState<VoiceName | null>(null);
  const [loadingVoice, setLoadingVoice] = useState<VoiceName | null>(null);
  const [errorVoice, setErrorVoice] = useState<VoiceName | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  const handlePlayPreview = async (e: React.MouseEvent, voice: VoiceName) => {
    e.stopPropagation(); 

    if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current = null;
    }

    if (playingVoice === voice) {
        setPlayingVoice(null);
        return;
    }

    setLoadingVoice(voice);
    setErrorVoice(null);
    setErrorMessage(null);

    try {
        let base64Data: string | null = null;
        let retries = 2;
        const textToSpeak = previewText.trim() || "The quick brown fox jumps over the lazy dog.";

        while(retries > 0) {
            try {
                // Use the provided demo text and style instruction for the preview
                base64Data = await generateSpeechChunk(textToSpeak, voice, model, styleInstruction);
                break;
            } catch(err: any) {
                // Don't retry if it's a hard limit/auth error
                if (err.message && (err.message.includes('Limit is 0') || err.message.includes('API Key is missing'))) {
                    throw err;
                }

                if (err?.isRateLimit && retries > 1) {
                    await new Promise(r => setTimeout(r, 1500));
                    retries--;
                    continue;
                }
                throw err;
            }
        }

        if (!base64Data) throw new Error("Failed to generate preview");

        const pcmData = base64ToUint8Array(base64Data);
        const wavBlob = createWavFile(pcmData);
        const url = URL.createObjectURL(wavBlob);

        const audio = new Audio(url);
        audioRef.current = audio;

        audio.onended = () => {
            setPlayingVoice(null);
            URL.revokeObjectURL(url);
        };

        await audio.play();
        setPlayingVoice(voice);
        setLoadingVoice(null);

    } catch (error: any) {
        console.error("Preview failed:", error);
        setLoadingVoice(null);
        setPlayingVoice(null);
        setErrorVoice(voice);
        setErrorMessage(error.message || "Preview failed");
        alert(`Preview failed: ${error.message}`);
    }
  };

  return (
    <div className="grid grid-cols-2 gap-2">
            {Object.values(VoiceName).map((voice) => {
                const isSelected = selectedVoice === voice;
                const isPlaying = playingVoice === voice;
                const isLoading = loadingVoice === voice;
                const isError = errorVoice === voice;

                const isFemale = ['Kore', 'Aoede', 'Leda'].includes(voice);

                return (
                    <div
                        key={voice}
                        onClick={() => !disabled && onVoiceChange(voice)}
                        className={`
                            relative group flex flex-col items-center justify-center p-2 rounded-lg border cursor-pointer transition-all h-20
                            ${isSelected 
                                ? 'bg-indigo-600 border-indigo-500 shadow-md shadow-indigo-100' 
                                : isError 
                                    ? 'bg-red-50 border-red-200 hover:border-red-300' 
                                    : 'bg-white border-zinc-200 hover:border-zinc-300 hover:bg-zinc-50'
                            }
                            ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
                        `}
                        title={isError ? errorMessage || "Error" : voice}
                    >
                        <div className="flex items-center justify-between w-full mb-1">
                             <span className={`text-[10px] font-bold uppercase tracking-wider opacity-60 ${isSelected ? 'text-indigo-100' : isError ? 'text-red-400' : 'text-zinc-400'}`}>
                                {isFemale ? 'Fem' : 'Masc'}
                             </span>

                             <button
                                onClick={(e) => handlePlayPreview(e, voice)}
                                disabled={disabled || (loadingVoice !== null && loadingVoice !== voice)}
                                className={`
                                    w-5 h-5 rounded-full flex items-center justify-center transition-all
                                    ${isPlaying 
                                        ? 'bg-white text-indigo-600' 
                                        : isSelected ? 'bg-indigo-500 text-white hover:bg-white hover:text-indigo-600' 
                                        : isError ? 'bg-red-100 text-red-500 hover:bg-red-200'
                                        : 'bg-zinc-100 text-zinc-400 hover:bg-zinc-200 hover:text-zinc-600'
                                    }
                                `}
                            >
                                {isLoading ? (
                                    <Loader2 className="w-2.5 h-2.5 animate-spin" />
                                ) : isPlaying ? (
                                    <Square className="w-2 h-2 fill-current" />
                                ) : isError ? (
                                    <AlertCircle className="w-3 h-3" />
                                ) : (
                                    <Play className="w-2 h-2 ml-0.5 fill-current" />
                                )}
                            </button>
                        </div>

                        <div className="text-center">
                            <span className={`text-sm font-bold ${isSelected ? 'text-white' : isError ? 'text-red-700' : 'text-zinc-600 group-hover:text-zinc-900'}`}>
                                {voice}
                            </span>
                        </div>
                    </div>
                );
            })}
    </div>
  );
};

export default VoiceSelector;
